// French B2 practice rooms: 6 modules x 12 rooms x 3 questions.
window.frRooms = window.frRooms || {};
frRooms.B2 = [
  // Module 1: Debate & Argumentation
  [
    {t:"Debate key words",s:"Vocabulary",qs:[
      {q:"What does the verb 'réfuter' mean?",opts:["to refute","to refuse","to reflect","to repeat"],a:0,ex:"Réfuter means proving an argument wrong; 'to refuse' is refuser, a common false friend.",say:"réfuter"},
      {q:"What does 'peser le pour et le contre' mean?",opts:["to weigh the pros and cons","to push for and against","to decide very quickly","to take sides firmly"],a:0,ex:"Peser means to weigh; le pour et le contre are the arguments for and against."},
      {q:"Which word means 'admittedly' and concedes a point before 'mais'?",opts:["certes","pourtant","ainsi","donc"],a:0,ex:"Certes grants that something is true before a counterpoint introduced by mais."}]},
    {t:"Concession & addition phrases",s:"Vocabulary",qs:[
      {q:"What does 'Il n'en reste pas moins que...' mean?",opts:["The fact remains that...","There is nothing left of...","It is no less than...","It remains to be seen if..."],a:0,ex:"This phrase maintains a point despite what was just conceded: the fact remains that."},
      {q:"What does 'Force est de constater que...' mean?",opts:["One has to admit that...","One must prove by force that...","It is easy to claim that...","We should never note that..."],a:0,ex:"Force est de means 'one is obliged to'; constater means to observe, so: one has to admit."},
      {q:"Which connector is closest in meaning to 'en outre'?",opts:["de plus","en revanche","pourtant","sinon"],a:0,ex:"En outre and de plus both add a further argument; en revanche and pourtant express contrast."}]},
    {t:"Sounds of debate",s:"Pronunciation",qs:[
      {q:"Listen. How many syllables does 'certes' have in standard speech?",opts:["one","two","three","four"],a:0,ex:"The final -es of certes is silent, so it is pronounced as one syllable: /sɛʁt/.",say:"certes"},
      {q:"Listen. How is the 'in-' of 'indéniable' pronounced?",opts:["as the nasal vowel in 'vin'","like English 'in'","like 'ine' in 'fine'","like 'un' in 'under'"],a:0,ex:"'In' before a consonant is the nasal vowel /ɛ̃/, the same sound as in vin or pain.",say:"indéniable"},
      {q:"Listen. What links the two words in 'en outre'?",opts:["a liaison with an /n/ sound","a liaison with a /z/ sound","a liaison with a /t/ sound","no link at all"],a:0,ex:"En before a vowel makes an obligatory liaison: the n is heard, /ɑ̃.nutʁ/.",say:"en outre"}]},
    {t:"Certes... mais",s:"Grammar",qs:[
      {q:"Fill the gap: Certes, ce projet est coûteux, ___ il créera des emplois.",opts:["mais","donc","car","ainsi"],a:0,ex:"Certes concedes a point and mais introduces the counterpoint; donc and ainsi express consequence."},
      {q:"Fill the gap: Il est vrai que la réforme est impopulaire ; ___, elle est nécessaire.",opts:["toutefois","de plus","en outre","ainsi que"],a:0,ex:"After 'Il est vrai que' you need a contrast word like toutefois; de plus and en outre only add."},
      {q:"Fill the gap: Ce plan est économique. ___, il est écologique.",opts:["De plus","Certes","Pourtant","Cependant"],a:0,ex:"Both sentences are positive, so you add weight with de plus rather than contrast."}]},
    {t:"Avoir beau + infinitive",s:"Grammar",qs:[
      {q:"Fill the gap: J'ai beau ___, il ne me croit pas.",opts:["expliquer","expliqué","explique","expliquant"],a:0,ex:"Avoir beau is always followed by an infinitive: however much I explain, he doesn't believe me."},
      {q:"Fill the gap: Elle ___ beau travailler, elle n'obtient pas de promotion.",opts:["a","est","fait","va"],a:0,ex:"The structure uses avoir conjugated: elle a beau + infinitive = however hard she works."},
      {q:"Which sentence is correct?",opts:["Nous avons beau insister, rien ne change.","Nous sommes beau insister, rien ne change.","Nous avons beaux insisté, rien ne change.","Nous avons beau d'insister, rien ne change."],a:0,ex:"Beau stays invariable, takes avoir and is followed directly by an infinitive without de."}]},
    {t:"Reading: an opinion piece",s:"Reading",qs:[
      {q:"« Certes, le télétravail réduit les trajets, mais il isole certains salariés. » What does the author do?",opts:["grants an advantage, then raises a drawback","rejects remote work completely","praises remote work without reservation","describes a new law on remote work"],a:0,ex:"Certes... mais is the classic concede-then-counter pattern: a benefit, then a problem."},
      {q:"« Force est de constater que les mesures ont échoué. Il n'en reste pas moins que l'idée était bonne. » What does the writer think?",opts:["The measures failed, but the idea was good.","The idea was bad, but the measures worked.","The measures will succeed later on.","It is unclear whether the measures failed."],a:0,ex:"Force est de constater admits the failure; il n'en reste pas moins que maintains the idea's value."},
      {q:"« J'ai beau peser le pour et le contre, je n'arrive pas à me décider. » Which statement is true?",opts:["Despite weighing it up, the speaker can't decide.","The speaker made the decision very quickly.","The speaker refuses to think about the choice.","The speaker has only considered the advantages."],a:0,ex:"Avoir beau shows effort without result: weighing the pros and cons has not led to a decision."}]},
    {t:"Listening: in a debate",s:"Listening",qs:[
      {q:"Listen. How sure is the speaker?",opts:["completely certain","rather doubtful","indifferent","slightly hesitant"],a:0,ex:"Il est indéniable que expresses a strong claim: something cannot be denied.",say:"Il est indéniable que nous devons agir rapidement."},
      {q:"Listen. What is the speaker's position?",opts:["understands the view but disagrees","fully agrees with the view","does not understand the view","has just changed their mind"],a:0,ex:"Je comprends votre point de vue softens the disagreement, and cependant introduces the opposite opinion.",say:"Je comprends votre point de vue, cependant je ne le partage pas."},
      {q:"Listen. What is the speaker doing?",opts:["adding another argument","conceding a point","concluding the debate","asking a question"],a:0,ex:"De plus adds weight to an argument already made; here a further cost argument.",say:"De plus, cette mesure coûterait très cher aux contribuables."}]},
    {t:"Speaking: debating politely",s:"Speaking",qs:[
      {q:"Your opponent says: « Le vote à 16 ans est absurde. » You want to disagree politely. What do you say?",opts:["Je comprends votre point de vue, mais je pense le contraire.","Je suis tout à fait d'accord avec vous sur ce point.","Vous avez tort, c'est tout, il n'y a rien à ajouter.","Ouais, si tu veux, mais franchement ça m'étonnerait."],a:0,ex:"Acknowledging the other view before stating yours is the polite debate formula; tu is too casual here."},
      {q:"As moderator, you hand over to the next speaker. What do you say?",opts:["Je vous donne la parole.","Je vous prends la parole.","Je vous coupe la parole.","Je vous laisse sans parole."],a:0,ex:"Donner la parole means to give someone the floor; couper la parole means to interrupt them."},
      {q:"You want to concede a point and then counter it. Which sentence fits?",opts:["Certes, votre argument est valable, mais il néglige le coût.","De plus, votre argument est valable, et il néglige le coût.","Ainsi, votre argument est valable, donc il néglige le coût.","En outre, votre argument est faux, car il néglige le coût."],a:0,ex:"Certes grants the point and mais introduces the counter-argument; the others add or conclude."}]},
    {t:"Writing an argument",s:"Writing",qs:[
      {q:"Choose the correctly written sentence.",opts:["Il est indéniable que nous devons agir.","Il est indéniable que nous devions agir.","Il est indéniable de nous devons agir.","Il est indéniable que nous devoir agir."],a:0,ex:"Il est indéniable que expresses certainty, so it takes the indicative, not the subjunctive."},
      {q:"Fill the gap: Force est ___ constater que le débat avance.",opts:["de","à","que","pour"],a:0,ex:"The fixed expression is 'force est de + infinitive': one is obliged to."},
      {q:"Which word order is correct?",opts:["Il n'en reste pas moins que ce choix est risqué.","Il ne reste en pas moins que ce choix est risqué.","Il n'en pas reste moins que ce choix est risqué.","Il en ne reste pas moins que ce choix est risqué."],a:0,ex:"Ne and the pronoun en come before the verb (n'en reste), and pas follows the verb."}]},
    {t:"Debate culture in France",s:"Culture",qs:[
      {q:"How do candidates normally address each other in a televised French political debate?",opts:["with vous","with tu","with on","with nous"],a:0,ex:"Public debates are formal, so participants use vous even if they know each other well."},
      {q:"What is 'le débat de l'entre-deux-tours'?",opts:["the TV debate between the two run-off candidates","a debate among all first-round candidates","a debate in the Senate between parties","a school debating contest held twice a year"],a:0,ex:"Before the second round of the presidential election, the two remaining candidates debate on TV."},
      {q:"French essays often follow 'thèse, antithèse, synthèse'. What does the antithèse do?",opts:["presents the opposing arguments","summarises the final conclusion","introduces the topic and question","lists the sources used"],a:0,ex:"The antithèse examines the counter-arguments before the synthèse reconciles both sides."}]},
    {t:"Review: argumentation",s:"Review",qs:[
      {q:"Odd one out: which connector does NOT add an argument?",opts:["en revanche","de plus","en outre","par ailleurs"],a:0,ex:"En revanche introduces a contrast; de plus, en outre and par ailleurs add a further point."},
      {q:"What does the structure 'avoir beau + infinitive' express?",opts:["effort without the expected result","the reason behind an action","a goal or a clear purpose","a condition needed for success"],a:0,ex:"Avoir beau is concessive: however much you do something, the result does not follow."},
      {q:"Which phrase introduces a fact presented as certain?",opts:["Il est indéniable que","Il se peut que","Il semble que","Il est possible que"],a:0,ex:"Indéniable means undeniable; the other phrases express possibility or appearance."}]},
    {t:"Challenge: refuting arguments",s:"Challenge",qs:[
      {q:"Which sentence with a past infinitive is correct?",opts:["Ils ont beau avoir réfuté chaque argument, le public reste sceptique.","Ils ont beau ont réfuté chaque argument, le public reste sceptique.","Ils ont beaux avoir réfutés chaque argument, le public reste sceptique.","Ils ont beau d'avoir réfuté chaque argument, le public reste sceptique."],a:0,ex:"Avoir beau can take a past infinitive (avoir réfuté); beau and the participle stay invariable."},
      {q:"Which sentence best refutes an objection?",opts:["On objectera que cette mesure coûte cher ; or, elle se financera d'elle-même.","On objectera que cette mesure coûte cher ; donc, elle est bien trop chère.","On objectera que cette mesure coûte cher ; de plus, elle coûte très cher.","On objectera que cette mesure coûte cher ; ainsi, personne n'en voudra."],a:0,ex:"'On objectera que' states the counter-argument and 'or' brings in a fact that undermines it."},
      {q:"In « S'il est vrai que le projet est cher, il reste rentable », what does 'S'il est vrai que' express?",opts:["a concession","a condition","a cause","a purpose"],a:0,ex:"Here si does not set a condition: it grants a point (although it is true) before the counterpoint."}]}
  ],
  // Module 2: Passive Voice & Register
  [
    {t:"Register words",s:"Vocabulary",qs:[
      {q:"Which register is the verb 'bosser' (to work)?",opts:["familier","soutenu","courant","littéraire"],a:0,ex:"Bosser is casual, used with friends; travailler is neutral and œuvrer is formal."},
      {q:"What does 'œuvrer' mean?",opts:["to work (formal)","to open (formal)","to wonder","to offer"],a:0,ex:"Œuvrer is a formal verb for working, often for a cause: œuvrer pour la paix."},
      {q:"What does « Ce produit se vend bien » mean?",opts:["This product sells well.","This product is sold out.","This product is well made.","This product is on sale."],a:0,ex:"Se vendre bien is a pronominal passive: the product is sold in large numbers."}]},
    {t:"Formal & casual pairs",s:"Vocabulary",qs:[
      {q:"Which verb is the most formal way to say 'to get' a diploma?",opts:["obtenir","choper","avoir","décrocher"],a:0,ex:"Obtenir belongs to formal, written register; avoir is neutral and choper is slang."},
      {q:"What is the neutral word for the casual 'une bagnole'?",opts:["une voiture","un vélo","un bateau","une moto"],a:0,ex:"Bagnole is familier for a car; in neutral French you say une voiture."},
      {q:"What does 'on dit que' mean?",opts:["people say that","one day that","we said that","they will say that"],a:0,ex:"On here is an impersonal subject, a common active alternative to 'it is said that'."}]},
    {t:"Literary forms & vowels",s:"Pronunciation",qs:[
      {q:"Listen to 'il fut'. Which word sounds exactly like 'fut'?",opts:["fût","fou","feu","fuit"],a:0,ex:"Fut and fût are both pronounced /fy/; the circumflex changes the meaning, not the sound.",say:"il fut"},
      {q:"Listen. The 'œu' in 'œuvrer' sounds like the vowel in...",opts:["sœur","sous","seau","sur"],a:0,ex:"Œu before a pronounced consonant is the open vowel /œ/, as in sœur or cœur.",say:"œuvrer"},
      {q:"Listen. Which letter of 'construit' is silent?",opts:["the final t","the first c","the r","the s"],a:0,ex:"Final t is usually silent: construit is pronounced /kɔ̃s.tʁɥi/.",say:"Le pont a été construit."}]},
    {t:"Building the passive",s:"Grammar",qs:[
      {q:"Fill the gap: Le texte ___ lu par tous les élèves.",opts:["est","a","se","fait"],a:0,ex:"The passive is formed with être + past participle: le texte est lu."},
      {q:"Fill the gap: Les décisions ont été ___ par le conseil.",opts:["prises","pris","prise","prenues"],a:0,ex:"In the passive the participle agrees with the subject: les décisions (fem. plural) → prises."},
      {q:"Fill the gap: Le projet a été financé ___ l'État.",opts:["par","pour","avec","à"],a:0,ex:"The agent of a passive verb is introduced by par."}]},
    {t:"Alternatives to the passive",s:"Grammar",qs:[
      {q:"Which sentence turns « Le français est parlé ici » into an active sentence?",opts:["On parle français ici.","On est parlé français ici.","Se parle français ici.","On parlé français ici."],a:0,ex:"With an unknown agent, French often prefers on + active verb to the passive."},
      {q:"Fill the gap: Il ___ voler son portefeuille dans le métro.",opts:["s'est fait","s'a fait","est fait","s'est faite"],a:0,ex:"Se faire + infinitive shows something happening to the subject; fait stays invariable here."},
      {q:"Fill the gap: La salle ___ rénovée l'an prochain.",opts:["sera","aura","a été","était"],a:0,ex:"The future passive uses the future of être: sera + participle."}]},
    {t:"Reading: how it is made",s:"Reading",qs:[
      {q:"« Le fromage est fabriqué à partir de lait cru. Il est ensuite affiné pendant six mois. » What happens after the cheese is made?",opts:["It is matured for six months.","It is sold within six months.","It is heated for six hours.","It is mixed with raw milk."],a:0,ex:"Ensuite marks the next step and affiner means to mature or age a cheese."},
      {q:"« La cathédrale fut construite au XIIIe siècle. » What does 'fut construite' mean?",opts:["was built","will be built","would be built","is being built"],a:0,ex:"Fut is the passé simple of être, used in written texts; with a participle it forms a past passive."},
      {q:"« Mec, j'ai trop bossé cette semaine, je suis crevé. » Who is this most likely addressed to?",opts:["a friend","a minister","a newspaper reader","a job recruiter"],a:0,ex:"Mec, bosser and crevé are all familier, which only suits close friends."}]},
    {t:"Listening: news in the passive",s:"Listening",qs:[
      {q:"Listen. Who opened the museum?",opts:["the president","the mayor","the minister","the architect"],a:0,ex:"Par introduces the agent: inauguré par le président.",say:"Le musée a été inauguré par le président en 2015."},
      {q:"Listen. What is said about the model?",opts:["It sells very well in Europe.","It is sold only in Europe.","It was designed in Europe.","It sells badly in Europe."],a:0,ex:"Se vendre très bien is a pronominal passive meaning to sell very well.",say:"Ce modèle se vend très bien en Europe."},
      {q:"Listen. What is said about him?",opts:["He was the first to sail the Atlantic alone.","He will be the first to cross the Atlantic.","He crossed the Atlantic with a team.","He was the last to cross the Atlantic."],a:0,ex:"Fut is the passé simple of être (he was); en solitaire means alone.",say:"Il fut le premier à traverser l'Atlantique en solitaire."}]},
    {t:"Speaking: switching register",s:"Speaking",qs:[
      {q:"You tell your manager that you worked hard on a file. What do you say?",opts:["J'ai beaucoup travaillé sur ce dossier.","J'ai trop bossé sur ce truc, franchement.","J'ai grave bossé sur le dossier, quoi.","J'ai bossé comme un malade sur ce truc."],a:0,ex:"With a manager you use courant register: travailler and dossier, not bosser, truc or grave."},
      {q:"A journalist asks how the new bridge was funded. Which answer fits the formal context?",opts:["Il a été financé par la région.","C'est la région qui a filé le fric.","Ben, c'est la région qui a payé, quoi.","La région, elle a casqué pour le pont."],a:0,ex:"A passive with par is neutral-to-formal; filer le fric and casquer are slang."},
      {q:"A friend texts « T'as fini ton boulot ? » Which reply matches the casual register?",opts:["Ouais, c'est bouclé !","Certes, il fut achevé.","Oui, ledit travail est achevé.","Je vous confirme son achèvement."],a:0,ex:"Ouais and boucler (to wrap up) are casual; fut, ledit and vous confirme are far too formal for a friend."}]},
    {t:"Writing: passive agreement",s:"Writing",qs:[
      {q:"Which passive sentence is spelled correctly?",opts:["Les maisons ont été détruites par la tempête.","Les maisons ont été détruits par la tempête.","Les maisons ont étés détruites par la tempête.","Les maisons on été détruites par la tempête."],a:0,ex:"Été never agrees, but the passive participle agrees with the subject (détruites); ont is the verb, on a pronoun."},
      {q:"Fill the gap: Cette décision ___ par la direction hier.",opts:["a été prise","a été pris","est pris","avait prit"],a:0,ex:"Hier calls for the passé composé passive, and prise agrees with la décision."},
      {q:"Fill the gap in a formal email: Je vous ___ de bien vouloir m'envoyer le dossier.",opts:["prie","prends","dis","mets"],a:0,ex:"Je vous prie de bien vouloir is a fixed formal formula for a polite written request."}]},
    {t:"Registers in French life",s:"Culture",qs:[
      {q:"Where do you mainly meet the passé simple today?",opts:["in novels and history texts","in everyday conversation","in text messages","in phone calls"],a:0,ex:"The passé simple is a written, literary tense; speech uses the passé composé instead."},
      {q:"Words like 'meuf' (from femme) belong to verlan. What is verlan?",opts:["slang that reverses syllables","a formal administrative style","a dialect from Brittany","a set of official abbreviations"],a:0,ex:"Verlan (from l'envers) swaps syllables: femme → meuf; it is a casual, familier register."},
      {q:"What is the main role of the Académie française?",opts:["to watch over the French language","to run France's public schools","to award national film prizes","to train future diplomats"],a:0,ex:"Founded in 1635, it issues recommendations on usage and publishes the official dictionary."}]},
    {t:"Review: passive & register",s:"Review",qs:[
      {q:"Which sentence names the agent explicitly?",opts:["La maison a été vendue par l'agence.","La maison s'est vendue très vite.","On a vendu la maison hier.","La maison est déjà vendue."],a:0,ex:"Only a passive with par states who did the action; on and the pronominal passive hide the agent."},
      {q:"Fill the gap: Ce vin ___ frais.",opts:["se boit","se bois","se boire","se but"],a:0,ex:"The pronominal passive uses the 3rd person: ce vin se boit frais = this wine is drunk chilled."},
      {q:"Which list goes from casual to formal?",opts:["bosser, travailler, œuvrer","travailler, bosser, œuvrer","œuvrer, travailler, bosser","bosser, œuvrer, travailler"],a:0,ex:"Bosser is familier, travailler courant and œuvrer soutenu."}]},
    {t:"Challenge: tricky passives",s:"Challenge",qs:[
      {q:"What is the passive of « Le jury aurait choisi ce candidat »?",opts:["Ce candidat aurait été choisi par le jury.","Ce candidat serait été choisi par le jury.","Ce candidat aurait choisi par le jury.","Ce candidat aurait été choisit par le jury."],a:0,ex:"Keep the tense of avoir (aurait), add été and the participle choisi: aurait été choisi."},
      {q:"Fill the gap in a literary text: Ils ___ reçus par le roi.",opts:["furent","fûrent","furents","fussent"],a:0,ex:"Furent is the passé simple of être (3rd plural); fussent is the imperfect subjunctive."},
      {q:"Which sentence CANNOT be turned into a passive with être?",opts:["Paul ressemble à son père.","Paul repeint la cuisine.","Paul écrit la lettre.","Paul répare la voiture."],a:0,ex:"Only verbs with a direct object can be passive; ressembler à takes an indirect object."}]}
  ],
  // Module 3: Complex Connectors & Structure
  [
    {t:"Advanced connectors",s:"Vocabulary",qs:[
      {q:"What does 'néanmoins' mean?",opts:["nevertheless","therefore","meanwhile","moreover"],a:0,ex:"Néanmoins introduces a contrast with what precedes, like toutefois or pourtant."},
      {q:"What does 'si bien que' mean?",opts:["so that (result)","even though (concession)","as long as (condition)","unless (exception)"],a:0,ex:"Si bien que introduces a consequence and is followed by the indicative."},
      {q:"What does 'd'autant plus que' mean?",opts:["all the more so since","just as much as","not nearly as much as","more or less because"],a:0,ex:"D'autant plus que adds a reason that strengthens what was said before."}]},
    {t:"Contrast & nominalisation",s:"Vocabulary",qs:[
      {q:"Which noun comes from the verb 'améliorer'?",opts:["l'amélioration","l'améliorement","la mélioration","l'améliorance"],a:0,ex:"Many -er verbs form nouns in -ation: améliorer → l'amélioration."},
      {q:"Which noun comes from the verb 'développer'?",opts:["le développement","la développation","le développage","la développance"],a:0,ex:"Développer forms its noun with -ment, as in le développement durable."},
      {q:"Which connector means 'on the other hand'?",opts:["en revanche","dès lors","si bien que","de plus"],a:0,ex:"En revanche contrasts two facts; dès lors and si bien que express consequence."}]},
    {t:"Connector sounds",s:"Pronunciation",qs:[
      {q:"Listen. How many syllables does 'néanmoins' have?",opts:["three","two","four","five"],a:0,ex:"Né-an-moins: the é and the nasal an are separate vowels, and -oins is one syllable.",say:"néanmoins"},
      {q:"Listen. How does the ending of 'en travaillant' sound?",opts:["a nasal vowel, as in 'dans'","a nasal vowel, as in 'fin'","/ant/ with the t pronounced","a nasal vowel, as in 'bon'"],a:0,ex:"The -ant of the present participle is the nasal /ɑ̃/; the final t is silent.",say:"en travaillant"},
      {q:"Listen to 'quoique' (although). Which expression sounds identical but means something else?",opts:["quoi que","parce que","quelque","pourquoi"],a:0,ex:"Quoique (although) and quoi que (whatever) are pronounced the same; only spelling shows the difference.",say:"quoique"}]},
    {t:"Two-part connectors",s:"Grammar",qs:[
      {q:"Fill the gap: Elle parle non seulement français ___ allemand.",opts:["mais aussi","et aussi","ou aussi","donc aussi"],a:0,ex:"Non seulement is paired with mais aussi: not only... but also."},
      {q:"Fill the gap: Plus je pratique, ___ je parle.",opts:["mieux","plus bien","meilleur","le mieux"],a:0,ex:"In plus... plus proportions, 'more well' becomes mieux; 'plus bien' is wrong."},
      {q:"Fill the gap: Tu peux venir ___ lundi, ___ mardi.",opts:["soit... soit","si... si","sois... sois","tant... tant"],a:0,ex:"Soit... soit presents two alternatives (either... or); sois is a verb form of être."}]},
    {t:"Gérondif & result",s:"Grammar",qs:[
      {q:"Fill the gap: Il a appris l'anglais ___ des séries.",opts:["en regardant","en regardé","à regardant","en regarder"],a:0,ex:"The gérondif is en + present participle (-ant) and expresses manner: by watching."},
      {q:"Fill the gap: Il a beaucoup plu, ___ la route est fermée.",opts:["si bien que","bien que","alors que","quoique"],a:0,ex:"The closed road is a result of the rain, so you need si bien que, not a concession word."},
      {q:"Fill the gap: Quoiqu'il ___ fatigué, il continue.",opts:["soit","est","sera","serait"],a:0,ex:"Quoique (although) always takes the subjunctive: quoiqu'il soit."}]},
    {t:"Reading: linked arguments",s:"Reading",qs:[
      {q:"« Le prix de l'énergie a augmenté, si bien que de nombreuses familles réduisent leur chauffage. » Why do families heat less?",opts:["because energy costs more","because winters are milder","because heating is banned","because they moved house"],a:0,ex:"Si bien que links the cause (higher prices) to its result (less heating)."},
      {q:"« Paul adore la ville, tandis que sa sœur préfère la campagne. » Which statement is true?",opts:["They have opposite preferences.","They both love the city.","They both prefer the countryside.","Paul's sister lives in the city."],a:0,ex:"Tandis que contrasts two simultaneous facts about different people."},
      {q:"« Néanmoins, ce rapport présente des lacunes ; dès lors, ses conclusions restent fragiles. » What does the writer conclude?",opts:["The gaps make the conclusions weak.","The report has no weaknesses.","The conclusions are strong despite gaps.","The report was never published."],a:0,ex:"Dès lors (therefore) draws a consequence from the gaps (lacunes): the conclusions are fragile."}]},
    {t:"Listening: cause and manner",s:"Listening",qs:[
      {q:"Listen. What relationship is described?",opts:["less sleep, less concentration","more sleep, less concentration","sleep has no effect at all","less sleep, more concentration"],a:0,ex:"Moins... moins expresses proportion: the less you sleep, the less focused you are.",say:"Moins on dort, moins on est concentré."},
      {q:"Listen. What does she do while cooking?",opts:["She sings.","She reads.","She dances.","She phones."],a:0,ex:"En faisant is a gérondif showing two simultaneous actions: she sings while cooking.",say:"Elle chante en faisant la cuisine."},
      {q:"Listen. What makes the speaker even keener on the job?",opts:["the attractive salary","the short commute","the friendly team","the flexible hours"],a:0,ex:"D'autant plus que adds a strengthening reason: the salary is interesting.",say:"J'accepte le poste, d'autant plus que le salaire est intéressant."}]},
    {t:"Speaking: linking ideas",s:"Speaking",qs:[
      {q:"In a presentation you want to contrast two cities. Which sentence fits?",opts:["Paris est cher ; en revanche, Lyon est plus abordable.","Paris est cher ; de plus, Lyon est plus abordable.","Paris est cher ; si bien que Lyon est plus abordable.","Paris est cher ; dès lors, Lyon est plus abordable."],a:0,ex:"En revanche sets two facts against each other; the others add or state a consequence."},
      {q:"A friend asks how you improved your French. What do you answer?",opts:["En lisant beaucoup de romans.","En lu beaucoup de romans.","À lisant beaucoup de romans.","En lire beaucoup de romans."],a:0,ex:"The gérondif (en + -ant) answers 'how?': by reading many novels."},
      {q:"You want to say 'the sooner the better'. What do you say?",opts:["Plus tôt, mieux c'est.","Plus tôt, meilleur c'est.","Le plus tôt, le mieux.","Plus tôt, plus bien c'est."],a:0,ex:"The fixed proportional phrase is 'plus tôt, mieux c'est'; mieux replaces 'plus bien'."}]},
    {t:"Writing: structured texts",s:"Writing",qs:[
      {q:"Which concessive sentence is correct?",opts:["Bien qu'il soit tard, nous continuons.","Bien qu'il est tard, nous continuons.","Bien que il soit tard, nous continuons.","Bien qu'il sera tard, nous continuons."],a:0,ex:"Bien que takes the subjunctive and elides before il: bien qu'il soit."},
      {q:"Fill the gap to open a paragraph: ___, nous analyserons les causes ; ensuite, les conséquences.",opts:["Dans un premier temps","Néanmoins, par ailleurs","Si bien que d'abord","Tandis que, au début"],a:0,ex:"Dans un premier temps announces the first step and pairs with ensuite."},
      {q:"How do you write « Les prix ont augmenté » as a nominal headline?",opts:["Augmentation des prix","Augmenter des prix","Augmenté les prix","Augmentant des prix"],a:0,ex:"Nominal style replaces the verb with its noun: augmenter → l'augmentation."}]},
    {t:"Essays & literature",s:"Culture",qs:[
      {q:"What structure does a French school 'dissertation' usually follow?",opts:["an intro, a 2–3 part body, a conclusion","a list of bullet points and a summary","the conclusion first, then the evidence","a single paragraph without any parts"],a:0,ex:"French students learn a strict plan: introduction, développement in two or three parts, conclusion."},
      {q:"Who wrote the novel 'No et moi' (2007)?",opts:["Delphine de Vigan","Marguerite Duras","Annie Ernaux","Albert Camus"],a:0,ex:"Delphine de Vigan's novel about a teenager and a homeless girl is widely read in French schools."},
      {q:"In which register do 'néanmoins' and 'quoique' mostly appear?",opts:["formal and written","slang","children's speech","Belgian dialect"],a:0,ex:"These connectors are typical of careful writing and formal speech, less of casual conversation."}]},
    {t:"Review: connectors",s:"Review",qs:[
      {q:"Odd one out: which connector does NOT express contrast?",opts:["si bien que","alors que","tandis que","en revanche"],a:0,ex:"Si bien que expresses a result; the other three contrast two ideas."},
      {q:"In « Il a menti ; dès lors, personne ne le croit », what does 'dès lors' mean?",opts:["consequently","meanwhile","however","unless"],a:0,ex:"Dès lors introduces a consequence: since then / therefore nobody believes him."},
      {q:"What is the structure 'en + participe présent' called?",opts:["le gérondif","le subjonctif","le passé simple","le conditionnel"],a:0,ex:"En + -ant is the gérondif, used for manner, means or simultaneity."}]},
    {t:"Challenge: connector traps",s:"Challenge",qs:[
      {q:"Fill the gap: Plus il gagne d'argent, ___ il en dépense.",opts:["plus","le plus","de plus","tant"],a:0,ex:"Proportional plus... plus repeats bare plus, with no article and no de."},
      {q:"Fill the gap: ___ tu fasses, je te soutiendrai.",opts:["Quoi que","Quoique","Bien que","Malgré que"],a:0,ex:"Quoi que in two words means 'whatever'; quoique and bien que mean 'although'."},
      {q:"In which sentence is the gérondif used correctly?",opts:["En sortant du bureau, j'ai croisé Marie.","En sortant du bureau, la pluie a commencé.","En sortant du bureau, mon téléphone a sonné.","En sortant du bureau, le bus est passé."],a:0,ex:"The gérondif must share the main clause's subject: I left and I met Marie."}]}
  ],
  // Module 4: News Analysis & Abstract Ideas
  [
    {t:"News words",s:"Vocabulary",qs:[
      {q:"What does 'l'enjeu' mean?",opts:["the stake / the issue","the game / the play","the player / the team","the answer / the reply"],a:0,ex:"L'enjeu is what is at stake in a situation: les enjeux climatiques."},
      {q:"What does 'le gros titre' mean in a newspaper?",opts:["the headline","the main author","the back page","the long article"],a:0,ex:"Les gros titres are the headlines printed in large type."},
      {q:"What does 'partial(e)' mean in French?",opts:["biased","incomplete","temporary","impartial"],a:0,ex:"Partial means biased; 'incomplete' is partiel, a classic confusion."}]},
    {t:"Abstract nouns & trends",s:"Vocabulary",qs:[
      {q:"Which abstract noun comes from 'libre'?",opts:["la liberté","la librerie","la libresse","la librité"],a:0,ex:"Libre gives liberté with the suffix -té, like égal → égalité."},
      {q:"What is the opposite of 'la hausse'?",opts:["la baisse","la housse","l'essor","la montée"],a:0,ex:"La hausse is a rise and la baisse a fall; essor and montée also mean growth."},
      {q:"What does 'la couverture médiatique' mean?",opts:["media coverage","a media cover-up","a media ban","a media headline"],a:0,ex:"Couverture means coverage here: how much and how the media report on a topic."}]},
    {t:"Long abstract words",s:"Pronunciation",qs:[
      {q:"Listen. How many syllables does 'responsabilité' have?",opts:["six","five","four","seven"],a:0,ex:"Res-pon-sa-bi-li-té: French gives each syllable equal weight, with slight stress on the last.",say:"la responsabilité"},
      {q:"Listen. In 'un net recul', is the t of 'net' pronounced?",opts:["yes, /nɛt/","no, it is silent","yes, but as a /d/","yes, but as an /s/"],a:0,ex:"Net is one of the words whose final t is always pronounced, unlike most final consonants.",say:"un net recul"},
      {q:"Listen. The 'en' in 'l'enjeu' sounds like...",opts:["'an' in 'dans'","'in' in 'vin'","'on' in 'bon'","'en' in English 'pen'"],a:0,ex:"En and an are both the nasal vowel /ɑ̃/ in French.",say:"l'enjeu"}]},
    {t:"Reporting sources",s:"Grammar",qs:[
      {q:"Fill the gap: ___ un rapport de l'ONU, la pauvreté recule.",opts:["D'après","Après","Depuis","Pour"],a:0,ex:"D'après, like selon, attributes information to a source; après alone means 'after'."},
      {q:"Fill the gap: Selon la police, le suspect ___ en fuite.",opts:["serait","soit","serais","sois"],a:0,ex:"Journalists use the conditional (3rd person serait) for information that is not confirmed."},
      {q:"Which abstract noun comes from 'durable'?",opts:["la durabilité","la durance","la duration","le durement"],a:0,ex:"Adjectives in -able form nouns in -abilité: durable → durabilité, responsable → responsabilité."}]},
    {t:"Nominal style",s:"Grammar",qs:[
      {q:"Which sentence matches the headline « Hausse des prix »?",opts:["Les prix augmentent.","Les prix baissent.","Les prix restent stables.","Les prix sont fixés."],a:0,ex:"Headlines use nouns instead of verbs: la hausse = the prices go up."},
      {q:"Which is the nominal version of « Le gouvernement a décidé de réformer »?",opts:["la décision du gouvernement de réformer","le décidé du gouvernement de réformer","la décidance du gouvernement de réformer","le décision du gouvernement de réformer"],a:0,ex:"Décider becomes the feminine noun la décision, and the subject becomes du gouvernement."},
      {q:"Fill the gap: Le chômage ___ de 2 % l'an dernier.",opts:["a reculé","a recul","est reculé","a reculée"],a:0,ex:"Reculer takes avoir and its participle does not agree here: le chômage a reculé."}]},
    {t:"Reading: news items",s:"Reading",qs:[
      {q:"« Selon un sondage, 60 % des Français soutiennent la réforme. » What is the source of the figure?",opts:["a poll","the government","an editor","the president"],a:0,ex:"Selon introduces the source; un sondage is an opinion poll."},
      {q:"« Les faits : l'usine fermera en mars. Notre avis : c'est une erreur. » Which part is opinion?",opts:["that the closure is a mistake","that the factory will close","that it will close in March","that the factory exists"],a:0,ex:"Les faits states what will happen; notre avis gives the paper's judgement."},
      {q:"« Canicule : l'enjeu de la durabilité au cœur des débats » What is at the centre of the debates?",opts:["sustainability","tourism","media bias","unemployment"],a:0,ex:"Au cœur des débats means at the centre of the debates, and the issue (enjeu) is durabilité."}]},
    {t:"Listening: radio news",s:"Listening",qs:[
      {q:"Listen. What happened to unemployment?",opts:["It fell slightly.","It rose sharply.","It stayed the same.","It fell sharply."],a:0,ex:"A baissé means fell, and légèrement means slightly.",say:"D'après l'INSEE, le chômage a légèrement baissé ce trimestre."},
      {q:"Listen. What criticism is made of the newspaper?",opts:["Its coverage is biased.","Its coverage is too short.","Its coverage comes too late.","Its coverage is too costly."],a:0,ex:"Partial means biased; the paper's coverage of the elections is not neutral.",say:"Ce journal est très partial dans sa couverture des élections."},
      {q:"Listen. What trend is described?",opts:["a 10% rise in sales","a 10% drop in sales","ten new shops","stable sales"],a:0,ex:"Une hausse is a rise; dix pour cent des ventes is ten per cent of sales.",say:"On observe une hausse de dix pour cent des ventes."}]},
    {t:"Speaking: press review",s:"Speaking",qs:[
      {q:"In a press review you want to separate the facts from your opinion. Which sentence works?",opts:["Les faits sont clairs ; à mon avis, cependant, l'article exagère.","Les faits sont mon avis ; donc, l'article exagère clairement.","À mon avis sont les faits ; l'article, cependant, exagère.","Les faits, c'est mon avis, et l'article l'exagère beaucoup."],a:0,ex:"Les faits presents what is established, and à mon avis clearly marks your personal view."},
      {q:"A colleague says « Cet article est objectif. » You think it is biased. What do you reply?",opts:["Je le trouve plutôt partial.","Je le trouve plutôt partiel.","Je le trouve plutôt parti.","Je le trouve plutôt partagé."],a:0,ex:"Partial means biased; partiel means incomplete and partagé means shared or divided."},
      {q:"You summarise an article's main argument. What do you say?",opts:["En résumé, l'auteur soutient que...","En résumé, l'auteur soutient de...","En résumé, l'auteur soutient à...","En résumé, l'auteur soutient pour..."],a:0,ex:"Soutenir que means to argue or maintain that, and is followed by a clause."}]},
    {t:"Writing: a news summary",s:"Writing",qs:[
      {q:"Which sentence from a news summary is correct?",opts:["Selon les experts, la situation s'améliore.","Selon les experts, la situation s'améliorer.","Selon les experts, la situation s'amélioré.","Selons les experts, la situation s'améliore."],a:0,ex:"Selon never takes an s, and the verb must be conjugated: la situation s'améliore."},
      {q:"Fill the gap: On constate une nette ___ du nombre de touristes.",opts:["augmentation","augmenter","augmenté","augmentant"],a:0,ex:"After une nette you need a noun: l'augmentation (nominal style)."},
      {q:"Fill the gap: La ___ de l'entreprise dans cette crise est évidente.",opts:["responsabilité","responsable","responsabilisé","responsablement"],a:0,ex:"After the article la you need the abstract noun responsabilité."}]},
    {t:"The French press",s:"Culture",qs:[
      {q:"How is the daily newspaper Libération generally positioned?",opts:["on the left","on the far right","as a sports paper","as a regional paper"],a:0,ex:"Founded in 1973 with Jean-Paul Sartre's support, Libération is a left-leaning national daily."},
      {q:"What is 'la une' of a newspaper?",opts:["the front page","the editorial","the TV guide","the back page"],a:0,ex:"Être à la une means to be on the front page, i.e. top news."},
      {q:"What does AFP stand for?",opts:["Agence France-Presse","Association française de presse","Agence fédérale de publication","Archives françaises de presse"],a:0,ex:"The AFP is France's major international news agency, supplying news to media worldwide."}]},
    {t:"Review: news analysis",s:"Review",qs:[
      {q:"Odd one out: which is NOT a word for a trend?",opts:["le gros titre","la hausse","la baisse","le recul"],a:0,ex:"Hausse, baisse and recul describe movements in figures; le gros titre is a headline."},
      {q:"What does « Il y a eu un net recul » mean?",opts:["There was a clear decline.","There was a clear rise.","There was a slight change.","There was no change."],a:0,ex:"Un recul is a fall or decline, and net means clear or marked."},
      {q:"Which phrase marks a claim as someone else's, not the journalist's?",opts:["selon le ministre","nous estimons","à notre avis","nous pensons"],a:0,ex:"Selon attributes the statement to a source; the others express the paper's own opinion."}]},
    {t:"Challenge: reading the press",s:"Challenge",qs:[
      {q:"A journalist writes « Le ministre aurait démissionné. » What does the conditional signal?",opts:["unconfirmed information","an established fact","a plan for the future","a polite request"],a:0,ex:"The conditionnel journalistique reports a claim without confirming it: reportedly resigned."},
      {q:"Which abstract noun comes from 'fragile'?",opts:["la fragilité","la fragilement","la fragileté","le fragilisme"],a:0,ex:"Like facile → facilité, fragile forms its noun with -ité."},
      {q:"Which headline is the most neutral?",opts:["Le gouvernement présente sa réforme des retraites","Le gouvernement impose enfin sa réforme scandaleuse","La réforme désastreuse du gouvernement passe","Retraites : le coup de force honteux du gouvernement"],a:0,ex:"Présente is neutral; scandaleuse, désastreuse and honteux reveal the writer's bias."}]}
  ],
  // Module 5: Negotiation, Presentation & Review
  [
    {t:"Negotiation words",s:"Vocabulary",qs:[
      {q:"What does 'trouver un compromis' mean?",opts:["to find a compromise","to compromise oneself","to make a promise","to break off a deal"],a:0,ex:"Un compromis is an agreement where each side gives something up."},
      {q:"What does 'faire un pas vers l'autre' mean in a negotiation?",opts:["to meet the other side halfway","to walk away from the table","to step down from a post","to take a short break"],a:0,ex:"Making a step towards the other means making a concession to reach agreement."},
      {q:"What is 'une critique constructive'?",opts:["constructive criticism","a building inspection","a harsh personal attack","a film review"],a:0,ex:"Constructive criticism points out weaknesses in a helpful way, with ideas to improve."}]},
    {t:"Presentation phrases",s:"Vocabulary",qs:[
      {q:"When do you say 'Pour conclure...' in an exposé?",opts:["at the end","at the start","to interrupt","to ask a question"],a:0,ex:"Pour conclure (to conclude) signals the final part of a talk."},
      {q:"What does 'étayer un argument' mean?",opts:["to support an argument","to delay an argument","to drop an argument","to summarise an argument"],a:0,ex:"Étayer means to prop up, so to back an argument with evidence or examples."},
      {q:"What does 'le chiffre d'affaires' mean?",opts:["turnover / revenue","the number of deals","the business card","the profit margin"],a:0,ex:"Le chiffre d'affaires is a company's total sales; profit is le bénéfice."}]},
    {t:"Presentation sounds",s:"Pronunciation",qs:[
      {q:"Listen. How is '-tion-' in 'mentionné' pronounced?",opts:["/sjɔ/, like 'sion'","/tjɔ/, with a hard t","/ʃɔ/, like 'chon'","like English 'shun'"],a:0,ex:"In -tion words the t is pronounced /s/: mention, nation, mentionné.",say:"Comme je l'ai mentionné"},
      {q:"Listen. Is the final s of 'un compromis' pronounced?",opts:["no, it is silent","yes, as an /s/","yes, as a /z/","yes, as a /ʃ/"],a:0,ex:"Final s is normally silent in French: compromis ends in the vowel /i/.",say:"un compromis"},
      {q:"Listen. What happens to the t of 'Tout' in 'Tout d'abord'?",opts:["it is silent","it is pronounced /t/","it becomes /d/","it links with a /z/"],a:0,ex:"Before a consonant (d'abord), the final t of tout is not pronounced.",say:"Tout d'abord"}]},
    {t:"Subjunctive in proposals",s:"Grammar",qs:[
      {q:"Fill the gap: Je propose que nous ___ une pause.",opts:["fassions","faisons","ferons","ferions"],a:0,ex:"Proposer que expresses a wish for an action, so it takes the subjunctive: que nous fassions."},
      {q:"Fill the gap: Nous acceptons, à condition que vous ___ le délai.",opts:["respectiez","respectez","respecterez","respecteriez"],a:0,ex:"À condition que always takes the subjunctive: que vous respectiez."},
      {q:"Soften the proposal with the conditional: Nous ___ nous mettre d'accord sur le prix.",opts:["pourrions","pouvons","pourrons","pouvions"],a:0,ex:"The conditionnel pourrions makes a proposal sound open and polite: we could agree."}]},
    {t:"Feedback & signposts",s:"Grammar",qs:[
      {q:"Use the conditional to soften feedback: Ton argument ___ être mieux étayé.",opts:["pourrait","pourra","puisse","pouvait"],a:0,ex:"The conditional pourrait turns a criticism into a suggestion: it could be better supported."},
      {q:"Which order of signposts is logical in a talk?",opts:["Tout d'abord → Ensuite → Pour terminer","Pour terminer → Tout d'abord → Ensuite","Ensuite → Pour terminer → Tout d'abord","Tout d'abord → Pour terminer → Ensuite"],a:0,ex:"Tout d'abord opens, ensuite continues and pour terminer closes the presentation."},
      {q:"Fill the gap: Comme le ___ ce graphique, les ventes augmentent.",opts:["montre","montrent","montré","montrer"],a:0,ex:"After comme le, the subject is inverted; ce graphique is singular, so montre."}]},
    {t:"Reading: a business email",s:"Reading",qs:[
      {q:"« Nous pourrions accepter un délai de deux semaines, à condition que le prix reste inchangé. » What is the condition?",opts:["The price must stay the same.","The delay must be longer.","Payment must be made now.","The order must be cancelled."],a:0,ex:"À condition que introduces the condition, and inchangé means unchanged."},
      {q:"« Comme le montre ce graphique, le chiffre d'affaires a doublé en deux ans. » What does the graph show?",opts:["Revenue doubled in two years.","Revenue halved in two years.","Costs doubled in two years.","Staff doubled in two years."],a:0,ex:"Le chiffre d'affaires is revenue, and a doublé means doubled."},
      {q:"« Ton exposé était clair. Toutefois, ta conclusion pourrait être plus développée. » What should be improved?",opts:["the conclusion","the introduction","the clarity","the slides"],a:0,ex:"Toutefois introduces the criticism, which concerns the conclusion; clarity is praised."}]},
    {t:"Listening: talks & deals",s:"Listening",qs:[
      {q:"Listen. Which part of the talk is this?",opts:["the closing","the opening","the first point","the Q&A section"],a:0,ex:"Pour terminer and thanking the audience mark the end of a presentation.",say:"Pour terminer, je voudrais vous remercier de votre attention."},
      {q:"Listen. What discount is proposed?",opts:["15%","50%","5%","20%"],a:0,ex:"Quinze is 15; à mi-chemin means meeting halfway.",say:"Je propose que nous nous retrouvions à mi-chemin : quinze pour cent de remise."},
      {q:"Listen. What does the speaker refer back to?",opts:["the limited budget","the tight deadline","the small team","the new clients"],a:0,ex:"Comme je l'ai mentionné refers back to something said earlier: le budget est limité.",say:"Comme je l'ai mentionné tout à l'heure, le budget est limité."}]},
    {t:"Speaking: negotiate & respond",s:"Speaking",qs:[
      {q:"A negotiation is stuck. What is the best way to propose a compromise?",opts:["Et si chacun faisait un pas vers l'autre ?","C'est à prendre ou à laisser, désolé.","Je refuse toute discussion sur ce point.","Vous n'avez qu'à accepter nos conditions."],a:0,ex:"Si + imparfait as a suggestion invites both sides to make a concession."},
      {q:"You give feedback to a classmate after an exposé. Which comment is constructive?",opts:["C'était clair ; tu pourrais ajouter des exemples.","C'était nul, je n'ai rien compris du tout.","Bof, ça manquait vraiment de tout, franchement.","Je n'ai pas écouté, mais c'était trop long."],a:0,ex:"Constructive feedback names a strength, then suggests an improvement with the conditional."},
      {q:"How do you begin your exposé?",opts:["Tout d'abord, je vais vous présenter le contexte.","Pour conclure, je vais vous présenter le contexte.","En résumé, je vais vous présenter le contexte.","Enfin, je vais vous présenter le contexte."],a:0,ex:"Tout d'abord opens a talk; pour conclure, en résumé and enfin belong at the end."}]},
    {t:"Writing: a proposal email",s:"Writing",qs:[
      {q:"Which sentence from a proposal email is correct?",opts:["Je propose que la réunion ait lieu lundi.","Je propose que la réunion a lieu lundi.","Je propose que la réunion aura lieu lundi.","Je propose que la réunion avoir lieu lundi."],a:0,ex:"Je propose que + subjunctive: avoir lieu becomes qu'elle ait lieu."},
      {q:"Fill the gap: Nous serions prêts à baisser nos tarifs, à condition que vous ___ une commande plus importante.",opts:["fassiez","faites","ferez","feriez"],a:0,ex:"À condition que requires the subjunctive: que vous fassiez."},
      {q:"Which sentence is correct for a report?",opts:["Comme le montrent ces chiffres, la demande baisse.","Comme le montre ces chiffres, la demande baisse.","Comme les montrent ces chiffres, la demande baisse.","Comme le montrant ces chiffres, la demande baisse."],a:0,ex:"The inverted subject ces chiffres is plural, so the verb is montrent; le stays as a neutral pronoun."}]},
    {t:"Business & exposé culture",s:"Culture",qs:[
      {q:"French students begin an exposé with an 'annonce du plan'. What is it?",opts:["a preview of the talk's parts","a joke to relax the audience","a list of the sources used","a thank-you to the teacher"],a:0,ex:"Announcing the plan tells listeners the structure (first, then, finally) before the content."},
      {q:"Which closing suits a formal French business email?",opts:["Je vous prie d'agréer mes salutations distinguées.","Bisous, à plus, et bon courage pour tout !","Ciao, bonne journée à toute l'équipe !","Grosses bises et à très bientôt, j'espère !"],a:0,ex:"Formal letters end with a fixed formula such as 'je vous prie d'agréer...'; bises and ciao are for friends."},
      {q:"In a negotiation, what does 'couper la poire en deux' mean?",opts:["to split the difference","to cut costs sharply","to end the talks","to share a meal"],a:0,ex:"Literally 'cut the pear in two', it means each side gives up half to reach a compromise."}]},
    {t:"Review: negotiation & talks",s:"Review",qs:[
      {q:"Which mood follows 'Je propose que...'?",opts:["the subjunctive","the indicative","the infinitive","the conditional"],a:0,ex:"Verbs of proposing or wishing followed by que take the subjunctive."},
      {q:"Odd one out: which is NOT a signpost for structuring a talk?",opts:["certes","tout d'abord","ensuite","pour terminer"],a:0,ex:"Certes concedes a point in an argument; the others order the steps of a talk."},
      {q:"What is 'Comme je l'ai mentionné...' used for?",opts:["to refer back to an earlier point","to announce a brand-new topic","to ask the audience a question","to disagree with a colleague"],a:0,ex:"It recalls something said earlier, which helps listeners follow a long talk."}]},
    {t:"Challenge: diplomatic French",s:"Challenge",qs:[
      {q:"Fill the gap: Nous accepterons, pourvu que vous nous ___ des garanties.",opts:["fournissiez","fournissez","fournirez","fourniriez"],a:0,ex:"Pourvu que (provided that), like à condition que, takes the subjunctive."},
      {q:"Which counter-proposal is the most diplomatic?",opts:["Votre offre est intéressante ; nous pourrions toutefois envisager un délai plus long.","Votre offre ne nous intéresse pas du tout ; il faut un délai beaucoup plus long.","Votre offre est franchement ridicule ; revenez avec un délai plus long.","Nous exigeons un délai plus long, point final, sinon nous partons."],a:0,ex:"It acknowledges the offer, then uses toutefois and the conditional to suggest change softly."},
      {q:"Fill the gap: Il faudrait que ton exposé ___ plus court.",opts:["soit","est","sera","serait"],a:0,ex:"Il faudrait que, like il faut que, is followed by the subjunctive: soit."}]}
  ],
  // Module 6: Si-clauses & Hypotheticals
  [
    {t:"Hypothetical phrases",s:"Vocabulary",qs:[
      {q:"In « À ta place, j'accepterais », what does 'à ta place' mean?",opts:["if I were you","at your house","in your seat","at your request"],a:0,ex:"À ta place followed by a conditional gives advice: if I were in your position."},
      {q:"What does 'regretter de + infinitif' mean?",opts:["to regret doing","to remember doing","to refuse to do","to repeat doing"],a:0,ex:"Regretter de is followed by an infinitive: je regrette d'être parti."},
      {q:"What does 'Ça vous dérangerait de... ?' mean?",opts:["Would you mind...?","Would you arrange...?","Did you disturb...?","Have you changed...?"],a:0,ex:"Déranger means to bother; the conditional makes it a polite request: would it bother you to...?"}]},
    {t:"Regrets & requests",s:"Vocabulary",qs:[
      {q:"What does 'Si j'avais su...' mean?",opts:["If I had known...","If I knew...","If I know...","If I will know..."],a:0,ex:"Avais su is the plus-que-parfait, used for a past that did not happen: if I had known."},
      {q:"What does 'Pourriez-vous... ?' mean?",opts:["Could you...?","Can I...?","Would you like...?","Should you...?"],a:0,ex:"Pourriez is the conditional of pouvoir with vous: a polite 'could you'."},
      {q:"Which sentence expresses a regret about the past?",opts:["Si j'avais su, je serais venu.","Si tu viens, on ira au parc.","Si j'ai le temps, je t'appelle.","Si je pouvais, je voyagerais."],a:0,ex:"Si + plus-que-parfait with the conditionnel passé talks about an unreal past."}]},
    {t:"Conditional sounds",s:"Pronunciation",qs:[
      {q:"Listen. Which spelling is correct for this form meaning 'I would like'?",opts:["je voudrais","je voudrai","je voudrait","je voudrez"],a:0,ex:"The conditional of je ends in -ais; je voudrai (no s) is the future.",say:"je voudrais"},
      {q:"Listen. How is 'S'il' pronounced?",opts:["/sil/, like 'cil'","/si.il/, two syllables","/sɛl/, like 'sel'","/zil/, with a z sound"],a:0,ex:"Si elides before il, giving the single syllable s'il /sil/.",say:"S'il avait su"},
      {q:"Listen. What sound links 'nous' and 'aurions'?",opts:["a /z/ liaison","an /s/ sound","a /t/ liaison","no link at all"],a:0,ex:"Final s before a vowel makes a liaison pronounced /z/: nous‿aurions.",say:"nous aurions"}]},
    {t:"Si + present / imparfait",s:"Grammar",qs:[
      {q:"Fill the gap: Si tu viens, on ___ au parc.",opts:["ira","irait","serait allé","allait"],a:0,ex:"A real condition (si + present) is followed by the present, futur or imperative."},
      {q:"Fill the gap: Si j'___ le temps, je voyagerais.",opts:["avais","aurais","ai","aurai"],a:0,ex:"A hypothesis uses si + imparfait with the conditionnel présent in the main clause."},
      {q:"Fill the gap: Si j'étais toi, j'___ l'offre.",opts:["accepterais","accepterai","acceptais","accepte"],a:0,ex:"After si + imparfait the result is in the conditionnel: j'accepterais."}]},
    {t:"Past regrets & typical errors",s:"Grammar",qs:[
      {q:"Fill the gap: Si j'avais su, je ___ venu.",opts:["serais","aurais","suis","étais"],a:0,ex:"Venir forms compound tenses with être, so the conditionnel passé is je serais venu."},
      {q:"Fill the gap: S'il avait pris le train, il ___ à l'heure.",opts:["serait arrivé","aurait arrivé","sera arrivé","était arrivé"],a:0,ex:"Si + plus-que-parfait → conditionnel passé; arriver takes être."},
      {q:"Which sentence is WRONG?",opts:["Si j'aurais le temps, je viendrais.","Si j'avais le temps, je viendrais.","Si j'ai le temps, je viendrai.","Si j'avais eu le temps, je serais venu."],a:0,ex:"The conditional never comes directly after si (if); use the imparfait instead."}]},
    {t:"Reading: what if...",s:"Reading",qs:[
      {q:"« Si j'étais maire, je créerais plus de pistes cyclables. » Is the writer the mayor?",opts:["No, it is a hypothesis.","Yes, they are the mayor.","They were mayor in the past.","They will be mayor next year."],a:0,ex:"Si + imparfait + conditionnel describes an imagined, unreal situation in the present."},
      {q:"« Si nous avions réservé plus tôt, nous aurions eu des places. » What happened?",opts:["They booked late and got no seats.","They booked early and got seats.","They will book seats very soon.","They got seats without booking."],a:0,ex:"The plus-que-parfait and conditionnel passé describe the opposite of what really happened."},
      {q:"« Ça vous dérangerait de m'envoyer le compte rendu avant vendredi ? » What is the writer asking for?",opts:["the minutes before Friday","to cancel Friday's meeting","help writing a report","a phone call on Friday"],a:0,ex:"Un compte rendu is a report or the minutes; ça vous dérangerait de is a polite request."}]},
    {t:"Listening: dreams & regrets",s:"Listening",qs:[
      {q:"Listen. What would the speaker buy?",opts:["a house by the sea","a boat","a flat in Paris","a new car"],a:0,ex:"Si + imparfait (gagnais) with the conditional (achèterais) describes a dream: a house by the sea.",say:"Si je gagnais au loto, je m'achèterais une maison au bord de la mer."},
      {q:"Listen. What does the speaker imply?",opts:["You didn't listen, so you made a mistake.","You listened, so you avoided a mistake.","You will make this mistake tomorrow.","You made no mistake at all today."],a:0,ex:"An unreal past (si + plus-que-parfait) implies the opposite really happened: no listening, an error.",say:"Si tu avais écouté, tu n'aurais pas fait cette erreur."},
      {q:"Listen. What is the speaker asking for?",opts:["to close the window","to open the window","to close the door","to turn off the light"],a:0,ex:"Pourriez-vous + infinitive is a polite request; fermer la fenêtre means close the window.",say:"Pourriez-vous fermer la fenêtre, s'il vous plaît ?"}]},
    {t:"Speaking: advice & requests",s:"Speaking",qs:[
      {q:"A friend hesitates about a job offer. How do you advise them?",opts:["À ta place, j'accepterais.","À ta place, j'accepterai.","À ta place, j'acceptais.","À ta place, j'aurais accepte."],a:0,ex:"Advice with à ta place uses the conditionnel présent: j'accepterais."},
      {q:"You need help from a colleague you address as vous. What is the most polite request?",opts:["Ça vous dérangerait de m'aider un instant ?","Aidez-moi, et vite, j'ai pas le temps !","Vous m'aidez, oui ou non, maintenant ?","Il faut m'aider tout de suite, c'est tout."],a:0,ex:"The conditional dérangerait softens the request; imperatives and 'il faut' sound like orders."},
      {q:"You regret not studying enough for an exam. What do you say?",opts:["Si j'avais travaillé plus, j'aurais réussi.","Si j'aurais travaillé plus, j'aurais réussi.","Si j'ai travaillé plus, j'aurais réussi.","Si j'avais travaillé plus, j'avais réussi."],a:0,ex:"A past regret needs si + plus-que-parfait and the conditionnel passé in the main clause."}]},
    {t:"Writing: if I were mayor",s:"Writing",qs:[
      {q:"Which hypothesis is written correctly?",opts:["Si j'étais maire, je rénoverais les écoles.","Si je serais maire, je rénoverais les écoles.","Si j'étais maire, je rénoverai les écoles.","Si j'étais maire, je rénovais les écoles."],a:0,ex:"Imparfait after si, conditionnel présent (-rais) in the result clause."},
      {q:"Fill the gap: Je regrette de ne pas ___ venu.",opts:["être","avoir","était","suis"],a:0,ex:"Regretter de takes an infinitive; venir uses être, so the past infinitive is être venu."},
      {q:"Which polite request is written correctly?",opts:["Pourriez-vous m'envoyer le document ?","Pourriez-vous envoyer-moi le document ?","Pourriez-vous m'envoyez le document ?","Pourriez-vous me envoyer le document ?"],a:0,ex:"The object pronoun goes before the infinitive and elides before a vowel: m'envoyer."}]},
    {t:"Politeness & 'si'",s:"Culture",qs:[
      {q:"Why do French speakers say « Je voudrais » rather than « Je veux » in a shop?",opts:["the conditional sounds more polite","'je veux' is grammatically wrong","'je voudrais' is the future tense","'je veux' is only used in writing"],a:0,ex:"Je veux is correct but blunt; the conditional softens requests, which is expected in shops."},
      {q:"What does the saying « Avec des si, on mettrait Paris en bouteille » mean?",opts:["Hypotheticals change nothing.","Paris is far too expensive.","Anything is possible in Paris.","You should always plan ahead."],a:0,ex:"It mocks endless 'ifs': with enough hypotheses you could put Paris in a bottle."},
      {q:"« Tu n'as pas faim ? — Si ! » What does 'Si' mean here?",opts:["yes (contradicting a negative)","if (introducing a condition)","so (expressing intensity)","no (agreeing with a negative)"],a:0,ex:"Si replaces oui to say yes in reply to a negative question."}]},
    {t:"Review: si-clauses",s:"Review",qs:[
      {q:"Si + plus-que-parfait is followed by which tense in the main clause?",opts:["conditionnel passé","conditionnel présent","futur simple","présent"],a:0,ex:"The unreal past pattern is si + plus-que-parfait → conditionnel passé."},
      {q:"Which sentence describes a real, likely condition?",opts:["S'il pleut, nous resterons à la maison.","S'il pleuvait, nous resterions à la maison.","S'il avait plu, nous serions restés.","Si j'étais riche, je ne travaillerais plus."],a:0,ex:"Si + present with the futur describes something that can really happen."},
      {q:"What tense or mood is 'je voudrais'?",opts:["conditionnel présent","futur simple","imparfait de l'indicatif","subjonctif présent"],a:0,ex:"Future stem voudr- with imparfait endings (-ais) forms the conditionnel présent."}]},
    {t:"Challenge: mixed hypotheses",s:"Challenge",qs:[
      {q:"Fill the gap: Si j'avais accepté ce poste, je ___ aujourd'hui à Montréal.",opts:["vivrais","aurais vécu","vivrai","vivais"],a:0,ex:"A past condition with a present result (aujourd'hui) takes the conditionnel présent."},
      {q:"Fill the gap: Même si tu ___ insisté, il n'aurait pas cédé.",opts:["avais","aurais","as","avait"],a:0,ex:"Même si follows the same rules as si: plus-que-parfait, never the conditional."},
      {q:"Which request is the most formal?",opts:["Auriez-vous l'amabilité de me rappeler ?","Tu pourrais me rappeler ce soir, stp ?","Rappelle-moi dès que tu peux, merci !","Vous me rappelez demain matin, d'accord ?"],a:0,ex:"Auriez-vous l'amabilité de uses vous, inversion and the conditional: very formal and polite."}]}
  ]
];
